</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
const long long MOD_A=1000000007,MOD_B=998244353;
const int maxk=7,base=1000000;
long long n,order;
int answer;
int partial_sum[maxk];
vector<int> sequences[maxk];

void generate_sequences(int x,int length){
    order++, sequences[length].push_back(((order - x) % MOD_B + MOD_B) % MOD_B);
    partial_sum[length]=(partial_sum[length]+sequences[length].back())%MOD_A;
    if(length==6) return;
    for(int digit=0; digit<=9; digit++)
        generate_sequences(x*10+digit,length+1);
}

void process(long long x){
    if(x>n) return;
    if(x*base+base-1<=n && x*base*10>n){
        long long current_order=order;
        for(int i=0,mult=1;i<=6;i++,mult*=10){
            int size=sequences[i].size();
            int difference=((current_order - x*mult) % MOD_B + MOD_B) % MOD_B;
            int position=lower_bound(sequences[i].begin(),sequences[i].end(),MOD_B - difference)-sequences[i].begin();
            answer=(answer+1LL*difference*size+partial_sum[i])%MOD_A;
            answer=(answer-1LL*MOD_A*(size - position)%MOD_A+MOD_A)%MOD_A;
            order+=size;
        }
        return;
    }
    order++, answer=(answer+((order - x) % MOD_B + MOD_B) % MOD_B)%MOD_A;
    for(int digit=0; digit<=9; digit++)
        process(x*10+digit);
}

int main(){
    cin>>n;
    order=0; generate_sequences(0,0);
    for(int i=0;i<=6;i++) sort(sequences[i].begin(),sequences[i].end());
    order=0;
    for(int i=1;i<=9;i++) process(i);
    cout<<answer<<endl;
    return 0;
}
